for prof,rows in pairs(patches) do
    P.Catalog[prof]=P.Catalog[prof] or {}
    local bySpell,byItem={},{}
    for _,r in ipairs(P.Catalog[prof]) do if r.spell then bySpell[r.spell]=r elseif r.item then byItem[r.item]=r end end
    for _,r in ipairs(rows) do
        local old=bySpell[r.spell] or r.item and byItem[r.item]
        if old then
            if old.learn and r.learn and old.learn~=r.learn then
                r.wowheadLearn=r.learn
                r.sourceDiscrepancy="Training sources disagree: the Forever guide lists "..old.learn..", Wowhead lists "..r.learn..". The route retains the guide threshold; the live trainer is authoritative."
                r.learn=old.learn;r.yellow=old.yellow;r.green=old.green;r.grey=old.grey
            end
            -- Preserve a more informative curated acquisition note when the
            -- public list supplies no location; live reagents still win later.
            if not r.sourceVerified and old.source and old.sourceKind~="unknown" then
                r.source=old.source.."\n"..r.source
                if r.sourceKind=="unknown" then r.sourceKind=old.sourceKind end
            end
            for k,v in pairs(r) do old[k]=v end
            bySpell[r.spell]=old
            if r.item then byItem[r.item]=nil end
        else P.Catalog[prof][#P.Catalog[prof]+1]=r;bySpell[r.spell]=r end
    end
    for _,r in ipairs(P.Recipes[prof] or {}) do
        local fresh=bySpell[r.spell]
        if not fresh and r.item then
            for _,v in pairs(bySpell) do if v.item==r.item and v.name==r.name then fresh=v;break end end
        end
        if fresh and fresh.research then
            r.spell=fresh.spell
            r.mats=fresh.mats;r.source=fresh.source;r.acquisitionItems=fresh.acquisitionItems
            r.referenceURLs=fresh.referenceURLs
            r.learn=fresh.learn;r.yellow=fresh.yellow;r.green=fresh.green;r.grey=fresh.grey
            r.sourceDiscrepancy=fresh.sourceDiscrepancy
            if fresh.learn and r.start and fresh.learn>r.start then
                r.note=(r.note or "").."\nSource conflict: this route starts at "..r.start..", but Wowhead lists learning at "..fresh.learn..". Train/verify before following this step."
            end
        end
    end
end
