local indexed,titles={},{}
for _,q in ipairs(researchedQuests) do indexed[q.profession..":"..q.id]=q;titles[q.profession..":"..q.title]=true end
local combined={}
for _,q in ipairs(P.QuestGuide) do
    local replacement=q.id and indexed[q.profession..":"..q.id]
    if not replacement and not (not q.id and titles[q.profession..":"..q.title]) then combined[#combined+1]=q end
    if replacement and not q.title:find("Camping 101:",1,true) then replacement.text=replacement.text.."\n\nPlanning notes: "..q.text end
end
for _,q in ipairs(researchedQuests) do combined[#combined+1]=q end
table.sort(combined,function(a,b)if a.skill~=b.skill then return a.skill<b.skill end;if a.level~=b.level then return a.level<b.level end;return a.title<b.title end)
P.QuestGuide=combined
